out=[row[:] for row in grid]
bad=[]; all2=[]
for r,c in twos:
    orb={(r,c),(23-r,c),(r,23-c),(23-r,23-c)}
    vals=[grid[a][b] for a,b in orb if grid[a][b]!=2]
    if not vals: all2.append(sorted(orb))
    elif len(set(vals))>1: bad.append((r,c,[(a,b,grid[a][b]) for a,b in orb]))
    else: out[r][c]=vals[0]
len(all2),bad,[(r,c,grid[r][c],out[r][c]) for r,c in twos]

def d4(r,c):
    return {(r,c),(23-r,c),(r,23-c),(23-r,23-c),(c,r),(23-c,r),(c,23-r),(23-c,23-r)}
allvals={}; conflicts=[]
for r,c in twos:
    orb=d4(r,c); vals={grid[a][b] for a,b in orb if grid[a][b]!=2}
    if len(vals)>1: conflicts.append((r,c,vals))
    elif vals: out[r][c]=next(iter(vals))
    else: allvals[(r,c)]=orb
len(conflicts),conflicts[:5],len(allvals),allvals
